# AdBrain Chrome watchdog. Do NOT edit manually - regenerated by the installer.
# Runs every 5 minutes via a scheduled task. If the AdBrain Chrome (identified by
# --user-data-dir matching our isolated profile) is not running, relaunches it.
# Placeholders __PROFILE__ / __EXTDIR__ / __CHROME__ / __LOG__ are substituted
# by the installer at install-time.

$ErrorActionPreference = 'SilentlyContinue'
$profileDir = '__PROFILE__'
$extDir     = '__EXTDIR__'
$chromeExe  = '__CHROME__'
$logFile    = '__LOG__'

try {
    $needle = '--user-data-dir=' + $profileDir
    $running = @(Get-CimInstance Win32_Process -Filter "Name='chrome.exe'" |
                 Where-Object { $_.CommandLine -and ($_.CommandLine.Contains($needle)) }).Count -gt 0
    if (-not $running) {
        $launchArgs = '--user-data-dir="' + $profileDir + '" --load-extension="' + $extDir + '" --new-window "chrome://newtab"'
        Start-Process -FilePath $chromeExe -ArgumentList $launchArgs -WindowStyle Minimized
        $line = (Get-Date).ToString('s') + '  [relaunched]  ' + $chromeExe
        Add-Content -Path $logFile -Value $line
    }
} catch {
    $line = (Get-Date).ToString('s') + '  [error]  ' + $_.Exception.Message
    Add-Content -Path $logFile -Value $line
}
